{
  "name": "Delta Elektronika 单通道可编程直流电源",
  "name_en": "Delta Elektronika single-channel programmable DC power supply",
  "manufacturer": "Delta Elektronika",
  "description": "通过 PSC-ETH-2 以太网接口通信的单通道可编程直流电源，可用于实验中提供和调节输出电压、电流，并配置电压/电流限制以及保存、调用设备设置。",
  "description_en": "A single-channel programmable DC power supply accessed via the PSC-ETH-2 Ethernet interface. It is used in laboratory setups to source and adjust output voltage and current, configure voltage/current limits, and save or recall instrument settings.",
  "actions": [
    {
      "action_name": "auto-current",
      "description": "获取输出电流。",
      "description_en": "Get the output current."
    },
    {
      "action_name": "auto-current_max",
      "description": "获取最大输出电流。",
      "description_en": "Get the maximum output current."
    },
    {
      "action_name": "auto-recall",
      "description": "调用非易失性存储器中的设置。",
      "description_en": "Recall settings from non-volatile memory."
    },
    {
      "action_name": "auto-reset",
      "description": "将设备重置为默认设置。",
      "description_en": "Reset the instrument to default settings."
    },
    {
      "action_name": "auto-save",
      "description": "将当前设置保存到非易失性存储器。",
      "description_en": "Save the current settings to non-volatile memory."
    },
    {
      "action_name": "auto-set_current_limit",
      "description": "设置/定义电流限制状态和数值。",
      "description_en": "Set/define the current limit status and value."
    },
    {
      "action_name": "auto-set_voltage_limit",
      "description": "设置/定义电压限制状态和数值。",
      "description_en": "Set/define the voltage limit status and value."
    },
    {
      "action_name": "auto-voltage",
      "description": "获取输出电压。",
      "description_en": "Get the output voltage."
    },
    {
      "action_name": "auto-voltage_max",
      "description": "获取最大输出电压。",
      "description_en": "Get the maximum output voltage."
    },
    {
      "action_name": "auto-name",
      "description": "获取设备名称。",
      "description_en": "Get the device name."
    },
    {
      "action_name": "auto-current_limit",
      "description": "获取电流限制状态和数值。",
      "description_en": "Get the current limit status and value."
    },
    {
      "action_name": "auto-voltage_limit",
      "description": "获取电压限制状态和数值。",
      "description_en": "Get the voltage limit status and value."
    }
  ],
  "tag_hints": [
    "programmable DC power supply",
    "single-channel output",
    "Ethernet control",
    "voltage/current sourcing",
    "current limit setting",
    "voltage limit setting",
    "non-volatile settings"
  ]
}

